import json, pickle, os
T='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
P='/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/archaeology/recs.pkl'
def blocks_text(c):
    if isinstance(c,str): return c
    out=[]
    for b in c:
        if isinstance(b,dict):
            if b.get('type')=='text': out.append(b.get('text',''))
            elif b.get('type')=='image': out.append('[image]')
            else: out.append(json.dumps(b)[:2000])
        else: out.append(str(b))
    return '\n'.join(out)
def build():
    recs=[]
    with open(T) as f:
        for n,l in enumerate(f,1):
            d=json.loads(l)
            t=d['type']
            r={'n':n,'t':t,'ts':d.get('timestamp'),'side':d.get('isSidechain')}
            if t=='assistant':
                bl=[]
                for b in d['message']['content']:
                    ty=b.get('type')
                    if ty=='text': bl.append(('text',b['text']))
                    elif ty=='tool_use': bl.append(('tu',b['id'],b['name'],b['input']))
                    elif ty=='thinking': bl.append(('think',b.get('thinking','')))
                r['b']=bl
                r['model']=d['message'].get('model')
            elif t=='user':
                m=d['message']
                c=m['content']
                bl=[]
                if isinstance(c,str): bl.append(('utext',c))
                else:
                    for b in c:
                        ty=b.get('type')
                        if ty=='tool_result':
                            bl.append(('tr',b.get('tool_use_id'),blocks_text(b.get('content','')) if not isinstance(b.get('content'),str) else b['content'],b.get('is_error')))
                        elif ty=='text': bl.append(('utext',b['text']))
                        else: bl.append(('other',json.dumps(b)[:500]))
                r['b']=bl
                r['meta']=d.get('isMeta'); r['origin']=d.get('origin'); r['turnOrigin']=d.get('turnOrigin'); r['promptSource']=d.get('promptSource')
                r['tur']=str(d.get('toolUseResult'))[:300] if d.get('toolUseResult') is not None else None
            elif t=='attachment':
                a=d['attachment']
                r['a']=a.get('type')
                r['txt']=json.dumps(a)[:100000] if a.get('type') in ('hook_additional_context','file','queued_command','invoked_skills','edited_text_file','task_reminder','skill_listing') else None
            elif t=='system':
                r['sub']=d.get('subtype'); r['txt']=json.dumps({k:v for k,v in d.items() if k in('content','compactMetadata')})[:3000]
            elif t=='queue-operation':
                r['op']=d.get('operation'); r['txt']=str(d.get('content'))[:200000]
            else:
                continue
            recs.append(r)
    pickle.dump(recs,open(P,'wb'))
    return recs
def load():
    if os.path.exists(P): return pickle.load(open(P,'rb'))
    return build()
if __name__=='__main__':
    r=build(); print(len(r))
EOF
