# output tokens per mid is not stored; approximate: sum of text/tu chars/4
outtok={}
for r in recs:
    if r['t']=='assistant':
        L=0
        for b in r['b']:
            if b[0]=='text': L+=len(b[1])
            elif b[0]=='tu': L+=len(json.dumps(b[3]))
        outtok[r['mid']]=outtok.get(r['mid'],0)+L/3.5
