    bn=[b['n'] for b in bounds]
    import bisect
    groups=collections.defaultdict(list)
    for x in ir:
        k=bisect.bisect_right(bn,x[0])-1
        groups[k].append(x)
    for k,b in enumerate(bounds):
        g=groups.get(k,[])
        steps={}
        for x in g:
            st=step_tokens(x[1])
            steps.setdefault(tu[x[1]][3],[]).append((x,st))
        tot_chars=sum(x[3] for x in g)
        # distinct steps tokens
        toks=0
        for mid,l in steps.items():
            st=l[0][1]
            if st: toks+=st[0]
        print(k,b['n'],b['ts'][5:16],'pre',b['txt'][b['txt'].find('preTokens'):][:20] if False else '', 'calls',len(g),'chars',tot_chars,'tokens(step-delta)',toks,'first',g[0][0] if g else None,byn[g[0][0]]['ts'][11:19] if g else '', 'matches',sum(x[2] for x in g))
